<script setup lang="ts">
import {confirmAction} from '../ui/confirm'
import { ref,onMounted } from 'vue'
import { useRoute } from 'vue-router'
import { request } from '../api'
import SnapshotView from './SnapshotView.vue'
const route=useRoute(),data=ref<any>(null),version=ref<any>(null),busy=ref(false),error=ref(''),notice=ref(''),scope=ref('content'),resolveAliases=ref(false),page=ref(1)
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e)}finally{busy.value=false}}
async function load(){data.value=await request('/admin/recovery/history/'+route.params.id+'?page='+page.value)}
function select(number:number){void run(async()=>{version.value=await request('/admin/recovery/history/'+route.params.id+'/'+number);scope.value='content'})}
async function restore(){if(!version.value||!data.value||!await confirmAction('将此历史内容恢复为新的草稿修订。现有历史保留，前台将暂不显示，需审核后重新发布。继续吗？'))return;void run(async()=>{const restored=await request('/admin/recovery/history/'+route.params.id+'/'+version.value.number+'/restore',{method:'POST',body:JSON.stringify({expected_revision:data.value.current.revision,scope:scope.value,...(resolveAliases.value?{resolve_place_aliases:true}:{}),confirmation:'恢复为新草稿'})});notice.value='历史已恢复为新的草稿修订；操作前版本保留，请到内容管理审核后发布'+(restored.recovery_warnings?.length?' · '+restored.recovery_warnings.join('；'):'');version.value=null;await load()})}
onMounted(()=>void run(load))
</script>
<template><main class="container history-admin"><h1>历史版本</h1><p class="muted">恢复生成新草稿，不删除任何已有修订。仅恢复正文和动态字段时，当前结构化关联保持不变；模板绑定使用快照记录的原版本。</p><p v-if="error" class="error" role="alert">{{error}}；未执行不安全的恢复，请重新读取或选择适用范围。</p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="busy" role="status">正在处理…</p><div v-if="data" class="history-layout"><aside class="card"><h2>{{data.current.title}}</h2><p>当前修订 {{data.current.revision}}</p><button v-for="v in data.items" :key="v.number" class="entry" :disabled="busy" @click="select(v.number)">修订 {{v.number}}<small>{{v.created_at}}</small></button><div class="actions"><button :disabled="busy||page<=1" @click="page--;run(load)">上一页</button><span>{{page}} / {{Math.max(1,Math.ceil(data.total/20))}}</span><button :disabled="busy||page*20>=data.total" @click="page++;run(load)">下一页</button></div><button class="quiet" :disabled="busy" @click="run(load)">重新读取当前版本</button></aside><section v-if="version" class="card"><h2>修订 {{version.number}} 与当前版本对照</h2><p class="scope-note">此快照保存：正文、动态字段{{version.scope.template?'、模板绑定':''}}{{version.scope.connections?'、媒体/地点/记录关联':''}}{{version.scope.life?'、旅行/照片分组':''}}。未记录的数据无法从该版本恢复。</p><div class="snapshot-comparison"><section><h3>所选历史</h3><SnapshotView :value="version.snapshot"/></section><section><h3>当前内容</h3><SnapshotView :value="data.current"/></section></div><label>恢复范围<select v-model="scope" aria-label="恢复范围"><option value="content">正文、动态字段及已记录的模板版本</option><option v-if="version.can_restore_full" value="full">完整已保存快照（含结构化关联与行程）</option></select></label><label v-if="scope==='full'" class="checks"><input v-model="resolveAliases" type="checkbox"/>确认将已合并的历史地点映射到保留的目标UUID（原快照不改写）</label><p>若历史关联对象已永久删除或无法安全使用，完整恢复会拒绝，不会静默丢弃。可改选仅正文与字段，保留当前关联。</p><button :disabled="busy||!!data.current.deleted_at" @click="restore">恢复此版本为新草稿</button><p v-if="data.current.deleted_at" class="muted">请先从回收站恢复文章。</p></section><p v-else class="card muted">选择一个历史版本，按字段类型阅读并对照当前内容。</p></div></main></template>
<style scoped>.history-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px}.snapshot-comparison{display:grid;grid-template-columns:1fr 1fr;gap:24px}.snapshot-comparison>section{min-width:0;padding:14px;border:1px solid var(--ui-line);border-radius:var(--ui-radius)}.scope-note{padding:14px;background:var(--ui-card)}.entry small{font-size:12px}@media(max-width:800px){.history-layout,.snapshot-comparison{grid-template-columns:1fr}.history-admin h1{font-size:28px}}
</style>
